For every $p\in[1,\infty]$, the $L^{p. $-spectrum $\sigma_{p}(\mathcal{L})$ of $\mathcal{L}$ is the image of $S_p$ under the map $\gamma$, which is precisely the set of all $w$ in $\mathbb{C}$ which satisfies
	\begin{equation}\label{equation 1.2}
	\left[\frac{1-\mbox{Re }(w)}{b\cosh(\delta_{p}\log q)}\right]^{2}+\left[\frac{\Im(w)}{b\sinh(\delta_{p}\log q)}\right]^{2}\leq 1,\text{ where }b=\frac{2\sqrt{q}}{q+1}.
	\end{equation}
	In particular, $\sigma_{2}(\mathcal{L})$ degenerates into the line segment $[1-b,1+b]$.}

The spherical Fourier transform $\hat{f}$ of a finitely supported radial function $f$  is defined by
\begin{equation}\label{Equation 2.6}
	\hat{f}(z)=\sum\limits_{x\in\mathfrak X}f(x)\phi_z(x)\quad\text{ where }z\in\mathbb C.
\end{equation}
The symmetric properties of the spherical function implies that $\hat{f}$ is even and $\tau$-periodic on $\mathbb{C}$. For $1<p\leq 2$, we define the space  $\mathcal{S}_p(\mathfrak{X})$ which consists of all those functions $f$ defined on $\mathfrak{X}$ such that
\begin{equation}\label{Equation 2.7}
\nu_{m}(f)=\sup\limits_{x\in\mathfrak{X}}(1+|x|)^{m}q^{|x|/p}|f(x)|<\infty,\text{ for all }m\in\mathbb{N}.
\end{equation}
It is known that $\mathcal{S}_p(\mathfrak{X})$ form Fr\'{e}chet space with respect to these countable seminorms $\nu_{m}(\cdot)$ and are also known as the $p$-Schwartz spaces of rapidly decreasing functions on $\mathfrak{X}$ (see \cite{CMS}). For $1<p\leq 2$, we also define the space $\mathcal{H}(S_{p})^{\#}$ of all even, $\tau$-periodic function $g$ on $S_{p}$ which are holomorphic on $S_{p}^{\circ}$, continuous on $\partial S_{p}$ and satisfies
\begin{equation}\label{Equation 2.8}
\mu_{m}(g)=\sup\limits_{z\in S_{p}}\left|\frac{d^m}{dz}g(z)\right|<\infty,\text{ for all }m\in\mathbb{N}.
\end{equation}
It was  proved in \cite{JF} that the spherical Fourier transform is a topological isomorphism from $\mathcal{S}_2(\mathfrak{X})^{\#}$ onto $\mathcal{H}(S_{2})^{\#}$. In fact a similar result also holds when we consider $1<p<2$. The proof is given in appendix.

 For $1<p\leq 2$, a linear functional $T:\mathcal{S}_p(\mathfrak{X})\rightarrow\mathbb{C}$ is said to be a $L^{p}$-tempered distribution if $\langle T,f_{n}\rangle\rightarrow 0$ whenever $\nu_{m}(f_{n})\rightarrow 0$ for all $m\in\mathbb{N}$. The distribution $T$ is said to be radial if
$$\langle T,f\rangle=\langle T,\varepsilon f\rangle,\text{ for all }f\in\mathcal{S}_p(\mathfrak{X}).$$
In fact the radial part of an $L^{p}$-tempered distribution $T$ is again an $L^{p}$-tempered distribution defined by
$$\langle\varepsilon T,f\rangle=\langle T,\varepsilon f\rangle,\text{ for all }f\in\mathcal{S}_p(\mathfrak{X}).$$
The left translation $\tau_{x}$ of $T$ by an element $x\in G$ is defined as follow if $f\in\mathcal{S}_p(\mathfrak{X})$ then
$$\langle \tau_{x}T,f\rangle=T(\tau_{x^{-1}}f)=T\ast f^{\ast}(x^{-1})$$
where $f^{\ast}(x)=f(x^{-1})$.
Finally, the spherical Fourier transform $\hat{T}$ of a radial $L^{p}$-tempered distribution $T$ is a linear functional on $\mathcal{H}(S_{p})^{\#}$ defined by the following rule:
$$\langle \hat{T},\psi\rangle=\langle T,f\rangle,\text{ where }\psi\in\mathcal{H}(S_{p})^{\#}\text{ and }\hat{f}=\psi.$$

It is known that $\mathcal{S}_p(\mathfrak{X})$ form Fr\'{e}chet space with respect to these countable seminorms $\nu_{m}(\cdot)$ and are also known as the $p$-Schwartz spaces of rapidly decreasing functions on $\mathfrak{X}$ (see \cite{CMS}). For $1<p\leq 2$, we also define the space $\mathcal{H}(S_{p})^{\#}$ of all even, $\tau$-periodic function $g$ on $S_{p}$ which are holomorphic on $S_{p}^{\circ}$, continuous on $\partial S_{p}$ and satisfies
\begin{equation}\label{Equation 2.8}
\mu_{m}(g)=\sup\limits_{z\in S_{p}}\left|\frac{d^m}{dz}g(z)\right|<\infty,\text{ for all }m\in\mathbb{N}.
\end{equation}
It was  proved in \cite{JF} that the spherical Fourier transform is a topological isomorphism from $\mathcal{S}_2(\mathfrak{X})^{\#}$ onto $\mathcal{H}(S_{2})^{\#}$. In fact a similar result also holds when we consider $1<p<2$. The proof is given in appendix.

It is obvious that $\mathcal{P}_{z}=\mathcal{P}_{z+\tau}$, where $\tau=2\pi/\log q$. We denote the torus $\mathbb R/\tau \mathbb Z$ by $\mathbb{T}$, which can be identified with the interval $[-\tau/2,\tau/2)$. Let $\mathcal L$ be the Laplacian on $\mathfrak X$ defined in (\ref{eq00}). It is a well-known fact that $\mathcal L \mathcal{P}_{z}\eta(x) =\gamma(z) \mathcal{P}_{z}\eta(x)$ for every $z$ in $\mathbb{C},$ where expression of $\gamma(z)$ is given in (\ref{eq01}). The elementary spherical function $\phi_z$ on $\mathfrak X$ is the Poisson transform of the constant function $\mathbf{1}$.
Note that $\phi_z$ is the radial eigenfunction of $\mathcal L$ with eigenvalue $\gamma(z)$ such that  $\phi_z(o)=1$.
 For a suitable function $f$ on $\mathfrak{X}$, its radialization $\varepsilon f$ is defined as
\begin{equation}\label{Equation 2.3}
	\varepsilon f(x)=\int\limits_{K}f(k\cdot x)dk,
\end{equation}
where $dk$ is the normalized measure on $K$. Some useful facts about radialization:
 \begin{enumerate}
	\item $\|\varepsilon f\|_{p,q}\leq\|f\|_{p,q}$ whenever $1<p<\infty$, $1\leq q\leq\infty$.
\item The operator  $\varepsilon$  commutes with the Laplacian $\mathcal{L}$, that is $\mathcal{L}(\varepsilon f)=\varepsilon(\mathcal{L}f).$
\item Also if $\mathcal L u=\gamma(z)u$ then $\varepsilon u (x)=u(o)\phi_z(x)$.
\end{enumerate}
The following expression of the function $\phi_z$ is well-known (see \cite{FTP1})
\begin{equation}\label{eqsf}
\phi_z(x)= \begin{cases}
\vspace*{.2cm} \left(\frac{q-1}{q+1}|x|+1\right)q^{-|x|/2}&\forall z\in\ \tau\mathbb Z\\
\vspace*{.2cm}\left(\frac{q-1}{q+1}|x|+1\right)q^{-|x|/2}(-1)^{|x|}&\forall z\in {\tau/2}+\tau\mathbb Z\\
\mathbf{c}(z)q^{{(iz-1/2)}|x|}+\mathbf{c}(-z)q^{{(-iz-1/2)}|x|}&\forall z\in\mathbb C\setminus(\tau/2)\mathbb Z,
\end{cases}
\end{equation}
where $\mathbf{c}$ is a meromorphic function given by
$$\mathbf{c}(z)=\frac{q^{1/2}}{q+1}\frac{q^{1/2+iz}-q^{-{1/2}-iz}}{q^{iz}-q^{-iz}}\quad\forall z\in (\tau/2)\mathbb Z.$$
It is easy to verify that $|\phi_{z}(x)|\leq 1$ for all $x\in\mathfrak X$ whenever $z\in S_1=\{z\in\mathbb C: |\Im z|\leq1/2\}$.
Now we give some $L^p-$type estimates of $\phi_{z}(x)$. For $p\in(1,\infty)$ we define
$$\delta_p=\frac{1}{p}-\frac{1}{2}\;\;\; \text{and}\;\;\; S_p=\{z\in\mathbb C: |\Im z|\leq|\delta_p|\}.$$
It is important to note that $\delta_p=-\delta_{p^{\prime}}$ and $S_{2}=\mathbb{R}$. We assume $\delta_1=-\delta_\infty=1/2$ so that $S_1=\{z\in\mathbb C: |\Im z|\leq1/2\}$. We shall henceforth write $S_p^\circ$ and $\partial{S_p}$ to denote the usual interior and boundary of $S_p$ respectively.  The following norm estimates of $\phi_{z}$ can be derived by using  (\ref{eqsf}) (see \cite{FTP1} for details).
\begin{Lemma}\label{phiz}
	Let $1<p<2$. Then
	\begin{enumerate}
		\item[$1.$] $\phi_z\in L^{p'}(\mathfrak X)\quad\text{if and only if}\quad z\in S_p^\circ$
		\item[$2.$] $\phi_z\in L^{p',\infty}(\mathfrak X)\quad\text{if and only if}\quad z\in S_p.$
		\item[$3.$] $\phi_z\notin L^{2,\infty}(\mathfrak X)$ if $z\in(\tau/2)\mathbb Z$ and $\phi_z\in L^{2,\infty}(\mathfrak X)$ if $z\in\mathbb R\setminus(\tau/2)\mathbb Z$.
	\end{enumerate}
\end{Lemma}
From the above lemma it is clear that $\gamma(S_p^\circ)$ lies in the point spectrum of the $\mathcal L,$ which is a bounded operator on $L^{p^\prime}(\mathfrak X)$.
The following observation given in \cite[page 4275]{CMS1} clarifies the spectrum $\sigma_{p}(\mathcal{L})$ of the Laplacian $\mathcal{L}$.

Furthermore, Strichartz also proved that the above result holds for Heisenberg groups but fails for hyperbolic 3-space.
It turns out that the negative result on hyperbolic 3-space can indeed be extended to homogeneous trees ( which can be considered as a discrete version of hyperbolic spaces). A homogeneous tree $\mathfrak{X}$ of degree $q+1$ is a connected graph with no loops such that every vertex is adjacent to $q+1$ other vertices. For details about notation and preliminary results, we refer to section 2. Henceforth we assume $q\geq 2$. The distance $d(x,y)$ between two vertices $x$ and $y$  defined as the number of edges joining $x$ and $y$. The natural Laplace operator (or Laplacian) $\mathcal L$ on $\mathfrak X$ is defined by
\begin{equation}\label{eq00}\mathcal Lf(x)=f(x)-\frac{1}{q+1}\sum\limits_{y:d(x,y)=1}f(y).\end{equation}

Conversely, assume $g\in\mathcal{H}(S_{p})^{\#}$. Then for all $r$ with $p<r\leq 2$, the function $g(\cdot+i\delta_{r})$ is an infinitely differentiable function of period $\tau$. Hence g has a Fourier series representation of the form $g(s)=\sum\limits_{n\in\mathbb{Z}}F(n)q^{ins}$, where
$$F(n)=\frac{1}{\tau}\int\limits_{-\tau/2}^{\tau/2}g(s)q^{-ins}ds$$
yields the $n^{\text{th}}$ Fourier co-efficient of the function $g$. Our aim is to prove that $F\in q^{-\delta_{p}|\cdot|}S_{ev}(\mathbb{Z})$. Applying the Cauchy's integral theorem to $g$, it is easy to verify that for every $r\in(p,2]$ and $n\in\mathbb{Z}$,
\begin{align}
F(n)&=\frac{1}{\tau}\int\limits_{-\tau/2}^{\tau/2}g(s+i\delta_{r})q^{-in(s+i\delta_{r})}ds=\frac{1}{\tau}\int\limits_{-\tau/2}^{\tau/2}g(s-i\delta_{r})q^{-in(s-i\delta_{r})}ds.\label{eq19}
\end{align}
Infact the first equality in (\ref{eq19}) can be proved using the closed rectangle
\begin{multline*}
\Gamma(z)=\{z\in\mathbb{C}:\Im z=0,-\tau/2\leq \mbox{Re } z\leq\tau/2\}\cup\{z\in\mathbb{C}: \mbox{Re } z=\tau/2,0\leq \Im z\leq\delta_{r}\}\\
\cup\{z\in\mathbb{C}:\Im z=\delta_{r},\tau/2\leq \mbox{Re } z\leq-\tau/2\}\cup\{z\in\mathbb{C}:\mbox{Re } z=-\tau/2,\delta_{r}\leq \Im z\leq 0\}.
\end{multline*}
Using the identities (\ref{eq19}) and noting that $g$ is even, one can easily prove that $F(-n)=F(n)$ for all $n\in\mathbb{N}$, that $F$ is even in $\mathbb{Z}$. Integrating by parts the second equation in (\ref{eq19}) (m times) and further using the Dominated convergence theorem and letting $r\rightarrow p$ we have,
\begin{equation}\label{eq21}
\lambda_{m}(q^{\delta_{p}|\cdot|}F)\leq C \mu_{m}(g)\quad\text{for every }m\in\mathbb{Z}_{+}.
\end{equation}
Hence there exists an unique $f\in\mathcal{S}_p(\mathfrak{X})^{\#}$ such that $\mathcal{A}f=F$ and $g=\hat{f}$. Further using equations (\ref{eq16}) and (\ref{eq21}) we conclude that
$$\nu_{m}(f)\leq C \mu_{m}(\hat{f})\quad\text{for every }m\in\mathbb{Z}_{+}.$$
This completes the proof.
\end{proof}

